const DB='unknown-agent-client', VERSION=1, MAX=1048576
const enc=new TextEncoder(), dec=new TextDecoder()
const open=()=>new Promise((resolve,reject)=>{const r=indexedDB.open(DB,VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains('meta'))d.createObjectStore('meta');if(!d.objectStoreNames.contains('keys'))d.createObjectStore('keys');if(!d.objectStoreNames.contains('events')){const s=d.createObjectStore('events',{keyPath:'id'});s.createIndex('sequence','sequence',{unique:true})}if(!d.objectStoreNames.contains('operations')){const s=d.createObjectStore('operations',{keyPath:'id'});s.createIndex('state','state')}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})
const req=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})
const done=t=>new Promise((resolve,reject)=>{t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})
const stable=v=>JSON.stringify(v,Object.keys(v).sort())
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')
const bytes=h=>new Uint8Array(h.match(/../g).map(x=>parseInt(x,16)))
async function sha(data){return hex(await crypto.subtle.digest('SHA-256',data))}
async function meta(key,value){const d=await open(),t=d.transaction('meta',value===undefined?'readonly':'readwrite'),s=t.objectStore('meta');if(value===undefined)return await req(s.get(key));s.put(value,key);await done(t)}
async function key(name){const d=await open(),t=d.transaction('keys','readwrite'),s=t.objectStore('keys');let value=await req(s.get(name));if(!value){if(name==='storage')value=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);else{const generated=await crypto.subtle.generateKey({name:'Ed25519'},true,['sign','verify']),pkcs8=await crypto.subtle.exportKey('pkcs8',generated.privateKey),raw=await crypto.subtle.exportKey('raw',generated.publicKey);value={privateKey:await crypto.subtle.importKey('pkcs8',pkcs8,{name:'Ed25519'},false,['sign']),publicKey:await crypto.subtle.importKey('raw',raw,{name:'Ed25519'},true,['verify'])}}s.put(value,name);await done(t)}return value}
async function seal(domain,id,payload){const raw=enc.encode(JSON.stringify(payload));if(raw.length>MAX)throw new Error('Payload exceeds 1 MiB');const iv=crypto.getRandomValues(new Uint8Array(12)),aad=enc.encode(`unknown-agent-client:v1:${domain}:${id}`),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},await key('storage'),raw);return {iv:[...iv],cipher:[...new Uint8Array(cipher)]}}
async function unseal(domain,id,value){try{return JSON.parse(dec.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(value.iv),additionalData:enc.encode(`unknown-agent-client:v1:${domain}:${id}`)},await key('storage'),new Uint8Array(value.cipher))))}catch{throw new Error('Encrypted local data failed authentication')}}
export async function identity(){let id=await meta('deviceId');if(!id){id=crypto.randomUUID();await meta('deviceId',id)}const pair=await key('signing'),pub=await crypto.subtle.exportKey('raw',pair.publicKey);return {deviceId:id,publicKey:hex(pub)}}
export async function configure(endpoint){const url=new URL(endpoint);if(url.protocol!=='https:'&&url.hostname!=='localhost')throw new Error('HTTPS is required');await meta('endpoint',url.origin)}
export async function settings(){const i=await identity();return {...i,endpoint:await meta('endpoint')||'',cursor:await meta('cursor')||'',enrolled:!!(await meta('enrolled'))}}
export async function enroll(token,capabilities=['approval.resolve','message.send']){const cfg=await settings();if(!cfg.endpoint)throw new Error('Configure an endpoint first');const canonical=JSON.stringify([...capabilities].sort());const proof=enc.encode(`unknown-agent-device-enroll:v1:${token}:${cfg.deviceId}:${cfg.publicKey}:${canonical}`),sig=hex(await crypto.subtle.sign('Ed25519',(await key('signing')).privateKey,proof));const response=await fetch(`${cfg.endpoint}/v1/client/enroll`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token,device_id:cfg.deviceId,name:navigator.userAgent.slice(0,120),public_key:cfg.publicKey,capabilities,signature:sig})});if(!response.ok)throw new Error(`Enrollment failed (${response.status})`);await meta('enrolled',true);return await response.json()}
export async function queue(kind,payload,id=crypto.randomUUID()){const d=await open(),existing=await req(d.transaction('operations').objectStore('operations').get(id));if(existing){const prior=await unseal('operation',id,existing.payload);if(JSON.stringify(prior)!==JSON.stringify(payload)||existing.kind!==kind)throw new Error('Operation id conflict');return id}const record={id,kind,payload:await seal('operation',id,payload),state:'pending',created_at:new Date().toISOString()};const t=d.transaction('operations','readwrite');t.objectStore('operations').add(record);await done(t);return id}
export const resolveApproval=(id,approved,reason='')=>queue('approval.resolve',{approval_id:id,approved,reason:reason.slice(0,2000)},`approval:${id}`)
export async function events(){const d=await open(),rows=await req(d.transaction('events').objectStore('events').index('sequence').getAll());return await Promise.all(rows.map(async r=>({...r,payload:await unseal('event',r.id,r.payload)})))}
async function pending(){const d=await open(),rows=await req(d.transaction('operations').objectStore('operations').index('state').getAll('pending'));return await Promise.all(rows.slice(0,100).map(async r=>({id:r.id,kind:r.kind,payload:await unseal('operation',r.id,r.payload),created_at:r.created_at})))}
async function signedHeaders(body){const cfg=await settings(),timestamp=Math.floor(Date.now()/1000),nonce=crypto.randomUUID().replaceAll('-',''),digest=await sha(body),proof=enc.encode(`unknown-agent-device-request:v1:${timestamp}:${nonce}:${digest}`),signature=hex(await crypto.subtle.sign('Ed25519',(await key('signing')).privateKey,proof));return {'content-type':'application/json','x-device-id':cfg.deviceId,'x-device-timestamp':`${timestamp}`,'x-device-nonce':nonce,'x-device-signature':signature}}
async function applySync(payload){if(JSON.stringify(payload).length>MAX)throw new Error('Sync response exceeds 1 MiB');const prepared=[];for(const e of payload.events||[])prepared.push({...e,payload:await seal('event',e.id,e.payload)});const d=await open(),t=d.transaction(['events','operations','meta'],'readwrite'),ev=t.objectStore('events'),ops=t.objectStore('operations');for(const e of prepared){const old=await req(ev.get(e.id));if(!old)ev.add(e);else if(old.sequence!==e.sequence)throw new Error('Event history conflict')}for(const id of payload.acknowledged_operation_ids||[]){const op=await req(ops.get(id));if(!op)throw new Error('Unknown operation acknowledgement');op.state='acknowledged';ops.put(op)}t.objectStore('meta').put(payload.cursor||'','cursor');await done(t)}
export async function sync(){const cfg=await settings();if(!cfg.endpoint||!cfg.enrolled)throw new Error('Configure and enroll this device first');const body=enc.encode(JSON.stringify({cursor:cfg.cursor,operations:await pending()}));let last;for(let attempt=0;attempt<4;attempt++){try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000),response=await fetch(`${cfg.endpoint}/v1/client/sync`,{method:'POST',headers:await signedHeaders(body),body,signal:controller.signal});clearTimeout(timer);if(!response.ok){if(response.status<500&&response.status!==429)throw new Error(`Sync rejected (${response.status})`);throw new Error(`Sync unavailable (${response.status})`)}const raw=await response.arrayBuffer();if(raw.byteLength>MAX)throw new Error('Sync response exceeds 1 MiB');const payload=JSON.parse(dec.decode(raw));await applySync(payload);return payload}catch(error){last=error;if(attempt===3)break;await new Promise(r=>setTimeout(r,Math.min(4000,250*2**attempt)))}}throw last}
export async function reset(){indexedDB.deleteDatabase(DB);location.reload()}
